import {
  Group,
  Mesh,
  PlaneGeometry,
  CylinderGeometry,
  SphereGeometry,
  Color,
  Box3,
  Vector3,
  DirectionalLight,
  DoubleSide,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, mix, smoothstep, vec2, vec3, length as lengthNode, clamp } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'orrery-mechanism';

  const colors =
    config.intent?.visualSpec?.colors ??
    config.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      gradientStops: [
        { at: 0, hex: '#0b0b10' },
        { at: 0.65, hex: '#101017' },
        { at: 1, hex: '#16161d' },
      ],
    };

  const disposables = [];
  const timelines = [];
  let tickerFn = null;
  let primHandles = [];

  // ---------- BACKDROP ----------
  const stops = colors.gradientStops && colors.gradientStops.length
    ? colors.gradientStops
    : [{ at: 0, hex: colors.background }, { at: 1, hex: colors.ink }];

  const toVec3 = (hex) => {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  const c0 = toVec3(stops[0].hex);
  const cMid = toVec3(stops[Math.min(1, stops.length - 1)].hex);
  const cEnd = toVec3(stops[stops.length - 1].hex);
  const midAt = stops.length > 2 ? stops[1].at : 0.65;

  const t = uv().y;
  let gradientNode = mix(c0, cMid, smoothstep(0.0, midAt, t));
  gradientNode = mix(gradientNode, cEnd, smoothstep(midAt, 1.0, t));

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = gradientNode;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------- LIGHTS (local rim/accent only; scene provides ambient+key) ----------
  const rim = new DirectionalLight(new Color('#ff2a38'), 0.7);
  rim.position.set(-2.5, 1.5, 3);
  root.add(rim);

  const fill = new DirectionalLight(new Color('#e8ecf2'), 0.5);
  fill.position.set(2.5, 2.5, 4);
  root.add(fill);

  // ---------- MECHANISM GROUP ----------
  const mechanism = new Group();
  mechanism.name = 'mechanism';
  root.add(mechanism);

  const metalMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface || '#14141a'),
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  if ('anisotropy' in metalMat) metalMat.anisotropy = 0.7;
  disposables.push(() => metalMat.dispose());

  // placeholder gear silhouettes (visible immediately, swapped when GLB resolves)
  const makeGearPlaceholder = (diameter) => {
    const geo = new CylinderGeometry(diameter / 2, diameter / 2, 0.12, 14, 1);
    const mesh = new Mesh(geo, metalMat);
    mesh.rotation.x = Math.PI / 2;
    disposables.push(() => geo.dispose());
    return mesh;
  };

  const primaryPlaceholder = makeGearPlaceholder(1.6);
  primaryPlaceholder.position.set(0, 0, 0);
  mechanism.add(primaryPlaceholder);

  const secondaryPlaceholder = makeGearPlaceholder(0.9);
  secondaryPlaceholder.position.set(1.15, 0.35, -0.1);
  mechanism.add(secondaryPlaceholder);

  let primaryGear = primaryPlaceholder;
  let secondaryGear = secondaryPlaceholder;

  // ---------- ARBOR SHAFTS ----------
  const shaftMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink || '#16161d'),
    roughness: 0.6,
    metalness: 0.3,
  });
  disposables.push(() => shaftMat.dispose());

  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 12);
  const primaryShaft = new Mesh(shaftGeo, shaftMat);
  primaryShaft.rotation.x = Math.PI / 2;
  primaryShaft.position.set(0, 0, 0);
  mechanism.add(primaryShaft);

  const secondaryShaft = new Mesh(shaftGeo, shaftMat);
  secondaryShaft.rotation.x = Math.PI / 2;
  secondaryShaft.position.set(1.15, 0.35, -0.1);
  mechanism.add(secondaryShaft);
  disposables.push(() => shaftGeo.dispose());

  // ---------- JEWEL PIVOT ----------
  const jewelGeo = new SphereGeometry(0.12, 24, 24);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ff2a38'),
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.15,
    metalness: 0.0,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.08);
  mechanism.add(jewel);
  disposables.push(() => { jewelGeo.dispose(); jewelMat.dispose(); });

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new PlaneGeometry(2.6, 1.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    depthWrite: false,
    side: DoubleSide,
  });
  const suv = uv();
  const dist = lengthNode(vec2(suv.x, suv.y).sub(vec2(0.5, 0.5)));
  const alpha = clamp(smoothstep(0.5, 0.15, dist), 0.0, 1.0).mul(0.5);
  shadowMat.opacityNode = alpha;
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.2, 0);
  root.add(contactShadow);
  disposables.push(() => { shadowGeo.dispose(); shadowMat.dispose(); });

  // ---------- TEXT ----------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'The going train', role: 'headline', typography: { fontSize: 68 } },
      { text: '34 COMPONENTS / HAND-FINISHED', role: 'caption', typography: { fontSize: 18 } },
    ];

  const textObjects = [];
  for (const item of items) {
    const isHeadline = item.role === 'headline';
    const fontSize = item.typography?.fontSize ?? (isHeadline ? 68 : 18);
    const color = isHeadline ? (colors.paper || '#e8ecf2') : (colors.paper || '#e8ecf2');
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'center',
      letterSpacingPx: isHeadline ? 0 : 1.5,
    });
    textObj.position.set(0, isHeadline ? -1.7 : -2.1, 0.01);
    root.add(textObj);
    textObjects.push(textObj);
  }

  // ---------- MESH LOAD (async, non-blocking) ----------
  const meshUrl = config.meshUrl;
  if (meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader
      .loadGLB(meshUrl)
      .then((gltf) => {
        const source = gltf.scene || gltf;
        if (!source) return;

        const normalize = (obj, targetDiameter) => {
          const box = new Box3().setFromObject(obj);
          const size = new Vector3();
          box.getSize(size);
          const maxDim = Math.max(size.x, size.y, size.z) || 1;
          const scale = targetDiameter / maxDim;
          obj.scale.setScalar(scale);
          const center = new Vector3();
          box.getCenter(center);
          obj.position.sub(center.multiplyScalar(scale));
        };

        const primaryInstance = source;
        primaryInstance.traverse((child) => {
          if (child.isMesh) child.material = metalMat;
        });
        normalize(primaryInstance, 1.6);
        primaryInstance.position.set(0, 0, 0);

        const secondaryInstance = source.clone(true);
        secondaryInstance.traverse((child) => {
          if (child.isMesh) child.material = metalMat;
        });
        normalize(secondaryInstance, 0.9);
        secondaryInstance.position.set(1.15, 0.35, -0.1);

        mechanism.remove(primaryPlaceholder);
        mechanism.remove(secondaryPlaceholder);
        mechanism.add(primaryInstance);
        mechanism.add(secondaryInstance);

        primaryGear = primaryInstance;
        secondaryGear = secondaryInstance;
      })
      .catch(() => {
        // keep placeholders on failure
      });
  }

  // ---------- MECHANICAL ROTATION (continuous, mechanism-appropriate) ----------
  tickerFn = (time, deltaMs) => {
    const dt = (deltaMs || 16.6) / 1000;
    if (primaryGear) primaryGear.rotation.z += 0.08 * dt;
    if (secondaryGear) secondaryGear.rotation.z -= 0.142 * dt;
  };
  gsap.ticker.add(tickerFn);

  // ---------- ENTRANCE (weighted-settle) ----------
  root.scale.set(0.92, 0.92, 0.92);
  const entranceTl = gsap.timeline();
  entranceTl
    .to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' })
    .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });
  timelines.push(entranceTl);

  textObjects.forEach((obj, i) => {
    obj.position.y -= 0.15;
    const tl = gsap.timeline({ delay: 0.1 + i * 0.08 });
    tl.to(obj.position, { y: obj.position.y + 0.15, duration: 0.6, ease: 'power2.out' });
    timelines.push(tl);
  });

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveConfigs = config.cinematicPrimitives ?? [
    { name: 'orbit', params: { speed: 0.08, radius: 0.2 }, trigger: 'time' },
  ];

  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(mechanism, prim.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------- EVENT HANDLERS ----------
  root.userData.handlers = {};

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    if (tickerFn) gsap.ticker.remove(tickerFn);
    timelines.forEach((tl) => tl.kill());
    primHandles.forEach((h) => {
      try {
        h.cleanup && h.cleanup();
      } catch (e) {
        /* noop */
      }
    });
    disposables.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        /* noop */
      }
    });
  };

  return root;
}
